using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace Frociart {
 internal sealed class FlowWatchWindow:Form {
  internal readonly TextBox Expression=Ui.TextBox();internal readonly ListView Results=new FlowListView{View=View.Details,FullRowSelect=true,MultiSelect=false,HideSelection=false};
  internal readonly FlowButton Add,Edit,Remove,Read,Step,Play;internal readonly Label Status=Ui.Label("",10,Ui.Muted);
  readonly FlowWatchExpressions.Session session;readonly Func<bool> running;readonly Label frame=Ui.Label("",10,Ui.Muted),label=Ui.Label("Espressione da osservare",10,Ui.Ink,true);
  readonly FlowScrollPanel viewport=new FlowScrollPanel{Dock=DockStyle.Fill,AutoScroll=true};readonly FlowLayoutPanel body=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true,WrapContents=false,FlowDirection=FlowDirection.TopDown,Padding=new Padding(18)};
  FlowInspectExpression.Context context;bool paused;int revision=-1,editing=-1;IList<FlowWatchExpressions.Row> rows=new List<FlowWatchExpressions.Row>();
  internal FlowWatchWindow(FlowWatchExpressions.Session session,Func<bool> running,Action refresh,Action step,Action play,int percent){
   this.session=session;this.running=running;editing=session.DraftIndex>=0&&session.DraftIndex<session.Expressions.Count?session.DraftIndex:-1;float scale=Math.Max(1,Math.Min(2,percent/100f));Text="Espressioni osservate — Frociart";Font=Ui.Font(10*scale);BackColor=Ui.Surface;MinimumSize=new Size(480,380);Size=new Size(850,680);StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;AutoScaleMode=AutoScaleMode.Dpi;
   var title=Ui.Label("Espressioni osservate",17*scale,Ui.Ink,true);title.AutoSize=true;body.Controls.Add(title);frame.AutoSize=true;frame.Font=Font;body.Controls.Add(frame);var help=Ui.Label("Fino a 8 espressioni, aggiornate in pausa nella chiamata scelta. La lista resta in questa sessione del progetto; non è salvata nel file.",10*scale,Ui.Muted);help.AutoSize=true;body.Controls.Add(help);
   Results.AccessibleName="Espressioni osservate e risultati nella chiamata scelta";Results.Font=Ui.Mono(11*scale);Results.Height=(int)(210*scale);Results.Columns.Add("Espressione",240);Results.Columns.Add("Risultato o errore",500);Results.SelectedIndexChanged+=delegate{UpdateActions();};Results.DoubleClick+=delegate{ReadSelected();};body.Controls.Add(Results);label.AutoSize=true;label.Font=Font;body.Controls.Add(label);Expression.Text=session.Draft;if(session.SelectionStart>=0&&session.SelectionEnd>=0)Expression.Select(Math.Min(Expression.TextLength,session.SelectionStart),Math.Min(Expression.TextLength,session.SelectionEnd)-Math.Min(Expression.TextLength,session.SelectionStart));Expression.MaxLength=FlowWatchExpressions.MaxLength;Expression.AccessibleName=label.Text;Expression.Font=Ui.Mono(12*scale);Expression.TextChanged+=delegate{session.Draft=Expression.Text;};Expression.KeyDown+=delegate(object s,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;Put();}};body.Controls.Add(Expression);
   var edits=new FlowLayoutPanel{AutoSize=true,WrapContents=true,Margin=Padding.Empty};Add=Ui.Button(editing<0?"Osserva":"Salva modifica",110,Put,true);Edit=Ui.Button("Modifica",110,EditSelected);Remove=Ui.Button("Rimuovi",110,RemoveSelected);Read=Ui.Button("Valore completo",160,ReadSelected);var clear=Ui.Button("Nuova",100,NewExpression);foreach(var b in new[]{Add,Edit,Remove,Read,clear}){SizeButton(b,scale);edits.Controls.Add(b);}body.Controls.Add(edits);Status.AutoSize=true;Status.Font=Font;Status.AccessibleName="Stato delle espressioni osservate";body.Controls.Add(Status);
   var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,AutoSize=true,WrapContents=true,Padding=new Padding(12)};Step=Ui.Button("Avanti",110,()=>{step();refresh();});Play=Ui.Button("Riprendi",120,()=>{play();refresh();},true);var close=Ui.Button("Chiudi",100,Close);foreach(var b in new[]{Step,Play,close}){SizeButton(b,scale);footer.Controls.Add(b);}CancelButton=close;viewport.Controls.Add(body);Controls.Add(viewport);Controls.Add(footer);viewport.ClientSizeChanged+=delegate{FitBody();};Shown+=delegate{Ui.FitStartupToScreen(this);FitBody();refresh();Expression.Focus();};Ui.ApplyTheme(this);FlowFormMotion.Attach(this);UpdateActions();
  }
  static void SizeButton(FlowButton b,float scale){b.Font=Ui.Font(10*scale);b.Width=Math.Max((int)(b.Width*scale),TextRenderer.MeasureText(b.Text,b.Font).Width+28);b.Height=Math.Max(36,b.Font.Height+18);}
  protected override void OnFormClosing(FormClosingEventArgs e){session.Draft=Expression.Text;session.DraftIndex=editing;session.SelectionStart=Expression.SelectionStart;session.SelectionEnd=Expression.SelectionStart+Expression.SelectionLength;base.OnFormClosing(e);}
  void FitBody(){Add.Width=Math.Max(Add.Width,TextRenderer.MeasureText(Add.Text,Add.Font).Width+28);int width=Math.Max(1,viewport.ClientSize.Width-body.Padding.Horizontal-5);foreach(Control c in body.Controls){c.Width=width;var l=c as Label;if(l!=null)l.MaximumSize=new Size(width,0);}Results.Columns[0].Width=Math.Max(100,width/3);Results.Columns[1].Width=Math.Max(140,width-Results.Columns[0].Width-6);body.PerformLayout();}
  internal void UpdateContext(FlowInspectExpression.Context value,bool paused,bool canStep,bool canPlay){bool changed=!ReferenceEquals(context,value)||this.paused!=paused||revision!=session.Revision;context=value;this.paused=paused;Step.Enabled=canStep;Play.Enabled=canPlay;Play.Text=running()?"Pausa":"Riprendi";frame.Text=value==null?(paused?"Nessuna chiamata disponibile":"In esecuzione · aggiornamento alla pausa"):value.FunctionName+" · passo "+value.Steps+(paused?" · valori in pausa":" · in esecuzione");if(changed)Render();}
  internal void Put(){try{session.Put(Expression.Text,editing);editing=-1;Expression.Clear();Add.Text="Osserva";Status.ForeColor=Ui.Muted;Status.Text="Espressione conservata per questa sessione del progetto.";Render();}catch(ArgumentException ex){Status.ForeColor=Ui.Red;Status.Text=ex.Message;Expression.Focus();}FitBody();}
  void NewExpression(){editing=-1;Add.Text="Osserva";Expression.Clear();Expression.Focus();}
  int SelectedIndex {get{return Results.SelectedIndices.Count==0?-1:Results.SelectedIndices[0];}}
  void EditSelected(){int index=SelectedIndex;if(index<0)return;editing=index;Expression.Text=session.Expressions[index];Add.Text="Salva modifica";Expression.Focus();Expression.SelectAll();}
  internal void RemoveSelected(){int index=SelectedIndex;if(index<0)return;session.Remove(index);if(editing==index)NewExpression();else if(editing>index)editing--;Status.Text="Espressione rimossa dalla lista.";Render();}
  void ReadSelected(){int index=SelectedIndex;if(index<0||index>=rows.Count)return;var row=rows[index];string value=row.Result==null?row.Error??row.Preview:FlowInspectExpression.Readable(row.Result);TutorTextDialog.ShowText(this,row.Expression,value);}
  void UpdateActions(){int index=SelectedIndex;Edit.Enabled=Remove.Enabled=index>=0;Read.Enabled=index>=0&&index<rows.Count&&paused;}
  void Render(){int selected=SelectedIndex;rows=FlowWatchExpressions.Read(session,context,paused);revision=session.Revision;Results.BeginUpdate();try{Results.Items.Clear();foreach(var row in rows){var item=new ListViewItem(row.Expression);item.SubItems.Add(row.Preview);item.Tag=row;item.ToolTipText=row.Preview;Results.Items.Add(item);}if(selected>=0&&selected<Results.Items.Count)Results.Items[selected].Selected=true;}finally{Results.EndUpdate();}UpdateActions();FitBody();}
  protected override bool ProcessCmdKey(ref Message message,Keys key){
   if(IsDisposed||Disposing)return false;var inspector=Owner as FlowVariableWindow;
   if(inspector!=null&&!inspector.IsDisposed&&!inspector.Disposing&&inspector.CommandKey!=null){var host=inspector.Owner;if(host==null||!host.IsDisposed&&!host.Disposing){if(inspector.CommandKey(key)){if(!IsDisposed&&!Disposing&&!inspector.IsDisposed&&!inspector.Disposing)inspector.RefreshState();return true;}}}
   return base.ProcessCmdKey(ref message,key);
  }
 }
}
